<?php require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/functions.php'; require_admin(); $pdo=db(); $stats=['users'=>$pdo->query('SELECT COUNT(*) c FROM users')->fetch()['c'],'clients'=>$pdo->query('SELECT COUNT(*) c FROM clients')->fetch()['c'],'reports'=>$pdo->query('SELECT COUNT(*) c FROM reports')->fetch()['c'],'revenue'=>$pdo->query("SELECT COALESCE(SUM(amount),0) c FROM payments WHERE status='paid'")->fetch()['c']]; ?>
<!doctype html><html><head><title>Admin</title><link rel="stylesheet" href="/assets/css/style.css"></head><body><main class="container"><h1>Admin Dashboard</h1><div class="grid"><?php foreach($stats as $label=>$value): ?><div class="card"><div class="stat"><?= is_numeric($value) ? e((string)$value) : e($value) ?></div><p><?= e(ucfirst($label)) ?></p></div><?php endforeach; ?></div><p><a href="/admin/users.php">Users</a> · <a href="/admin/revenue.php">Revenue</a></p></main></body></html>
